from typing import List
import re


class Regex(object):
    """
    A regular expression.
    """
    pass


class Empty(Regex):
    """
    A regular expression that matches the empty string.
    """

    def __str__(self) -> str:
        return ""


class Range(Regex):
    """
    A regular expression that matches a character range.
    """

    def __init__(self, low: str, high: str):
        if len(low) != 1 or len(high) != 1:
            raise ValueError("Range must be single characters")
        self.low = low
        self.high = high

    def __str__(self) -> str:
        return f'[{self.low}-{self.high}]'


class Choice(Regex):
    """
    A regular expression that matches a choice of regular expressions.
    """

    def __init__(self, *args: List[Regex]):
        if len(args) < 2:
            raise ValueError("Or must have at least two expressions")
        self.exprs = args

    def __str__(self) -> str:
        return f'({"|".join([str(e) for e in self.exprs])})'


class Seq(Regex):
    """
    A regular expression that matches a sequence of regular expressions.
    """

    def __init__(self, *args: List[Regex]):
        if len(args) < 2:
            raise ValueError("Seq must have at least two expressions")
        self.exprs = args

    def __str__(self) -> str:
        return f'({"".join([str(e) for e in self.exprs])})'


class Star(Regex):
    """
    A regular expression that matches zero or more iterations of a regular expression.
    """

    def __init__(self, r: Regex):
        self.expr = r

    def __str__(self) -> str:
        return f'({str(self.expr)})*'


def chars(low: str, high: str) -> Regex:
    """
    A regular that matches a character range.
    """
    return Range(low, high)


def text(s: str) -> Regex:
    """
    A regular that matches an exact string.
    """
    if s == "":
        return empty()
    elif len(s) == 1:
        return chars(s, s)
    else:
        return seq(*[chars(c, c) for c in s])


def choice(*args: List[Regex]) -> Regex:
    """
    A regular expression that matches a choice of regular expressions.
    """
    return Choice(*args)


def seq(*args: List[Regex]) -> Regex:
    """
    A regular expression that matches a sequence of regular expressions.
    """
    return Seq(*args)


def star(r: Regex) -> Regex:
    """
    A regular expression that matches zero or more iterations of a regular expression.
    """
    return Star(r)


def plus(r: Regex) -> Regex:
    """
    A regular expression that matches one or more iterations of a regular expression.
    """
    return seq(r, star(r))


def empty() -> Empty:
    """
    A regular expression that matches the empty string.
    """
    return Empty()


def ismatch(r: Regex, s: str) -> bool:
    """
    Determine if a string matches a regular expression.
    """
    regex = '^' + str(r) + '$'
    return re.match(regex, s) is not None

from ast import NodeVisitor
from typing import List, Dict
from eywa.ast import *
import eywa.regex as re

class TypeBuilder(NodeVisitor):
    """
    A class that converts an Eywa type to a C type.
    """

    @staticmethod
    def build(type: Type) -> str:
        """
        Convert an Eywa type to a C type as a string.
        """
        return TypeBuilder().visit(type)

    def visit_Void(self, node):
        return "void", ""

    def visit_Bool(self, node):
        return "bool", ""

    def visit_Char(self, node):
        return "char", ""

    def visit_Int(self, node):
        if node.size == 64:
            return "uint64_t", ""
        if node.size == 32:
            return "uint32_t", ""
        if node.size == 16:
            return "uint16_t", ""
        if node.size == 8:
            return "uint8_t", ""
        return "int", f": {node.size}"

    def visit_String(self, node):
        return "char*", ""

    def visit_Enum(self, node):
        return node.name, ""

    def visit_Array(self, node):
        (left, right) = self.visit(node.element_type)
        return left, f"{right}[{node.maxsize}]"

    def visit_Struct(self, node):
        return node.name, ""

    def visit_Alias(self, node):
        return node.name, ""


class DefinitionBuilder(NodeVisitor):
    """
    A class that creates a C type definition (if needed) for
    a given Eywa type. This includes enums, structs, and aliases.
    """

    @staticmethod
    def build(type: Type) -> str:
        """
        Build a C type definition for an Eywa type if necessary.
        """
        return DefinitionBuilder().visit(type)

    def visit_Void(self, node):
        return None

    def visit_Bool(self, node):
        return None

    def visit_Char(self, node):
        return None

    def visit_Int(self, node):
        return None

    def visit_String(self, node):
        return None

    def visit_Enum(self, node):
        return f'typedef enum {{ {", ".join(node.values)} }} {node.name};\n'

    def visit_Array(self, node):
        return None

    def visit_Struct(self, node):
        field_strs = []
        # print(node.fields.items())

        for (field_name, field) in node.fields.items():
            # print("Field:", field_name, field)
            (left, right) = TypeBuilder.build(field)
            field_strs.append(f"{left} {field_name}{right};")
            # print("Bye")
        fields = " ".join(field_strs)
        return f'typedef struct {{ {fields} }} {node.name};\n'

    def visit_Alias(self, node):
        (left, right) = TypeBuilder.build(node.type)
        description = "" if node.description is None else '\n'.join(
            [f'// {line}' for line in node.description.splitlines()]) + '\n'
        return f'{description}typedef {left} {node.name}{right};\n'


class TypeCollector(NodeVisitor):
    """
    A class to recursively extract all of the Ewya sub-types in a type.
    """

    @staticmethod
    def collect(type: Type, results: List[Type]):
        """
        Collect all the Eywa types in a given type.
        """
        TypeCollector(results).visit(type)

    def __init__(self, result):
        self.result = result

    def visit_Void(self, node):
        self.result.append(node)

    def visit_Bool(self, node):
        self.result.append(node)

    def visit_Char(self, node):
        self.result.append(node)

    def visit_Int(self, node):
        self.result.append(node)

    def visit_String(self, node):
        self.result.append(node)

    def visit_Enum(self, node):
        self.result.append(node)

    def visit_Array(self, node):
        self.visit(node.element_type)
        self.result.append(node)

    def visit_Struct(self, node):
        for (_, field) in node.fields.items():
            self.visit(field)
        self.result.append(node)

    def visit_Alias(self, node):
        self.visit(node.type)
        self.result.append(node)


class MainBuilder(NodeVisitor):
    """
    A class to build the KLEE main function that creates the symbolic
    inputs and runs the implementation given by the GPT model.
    """

    def __init__(self, result):
        self.result = result
        self.number = 0

    def _next(self):
        n = self.number
        self.number = self.number + 1
        return f'x{n}'

    def _is_array(self, node):
        while isinstance(node, Alias):
            node = node.type
        return isinstance(node, Array)

    def visit_Void(self, node):
        raise Exception('Cannot create an instance of the Void type')

    def visit_Bool(self, node):
        var = self._next()
        self.result.append(f'bool {var};')
        self.result.append(
            f'klee_make_symbolic(&{var}, sizeof({var}), "{var}");')
        return var

    def visit_Char(self, node):
        var = self._next()
        self.result.append(f'char {var};')
        self.result.append(
            f'klee_make_symbolic(&{var}, sizeof({var}), "{var}");')
        return var

    def visit_Int(self, node):
        var = self._next()
        self.result.append(f'{TypeBuilder.build(node)[0]} {var};')
        self.result.append(
            f'klee_make_symbolic(&{var}, sizeof({var}), "{var}");')
        return var

    def visit_String(self, node):
        var1 = self._next()
        self.result.append(f'char {var1}[{node.maxsize + 1}];')
        for i in range(0, node.maxsize):
            cvar = self.visit(node.char_type)
            # assign the char to the array.
            self.result.append(f'{var1}[{i}] = {cvar};')
        self.result.append(f"{var1}[{node.maxsize}] = '\\0';")
        return var1

    def visit_Enum(self, node):
        var = self._next()
        self.result.append(f'{node.name} {var};')
        self.result.append(
            f'klee_make_symbolic(&{var}, sizeof({var}), "{var}");')
        self.result.append(f'klee_assume({var} >= 0);')
        self.result.append(f'klee_assume({var} < {len(node.values)});')
        return var

    def visit_Array(self, node):
        var = self._next()
        (l, r) = TypeBuilder.build(node.element_type)
        self.result.append(f'{l} {var}{r}[{node.maxsize}];')
        for i in range(0, node.maxsize):
            evar = self.visit(node.element_type)
            self.result.append(f'{var}[{i}] = {evar};')
        return var

    def visit_Struct(self, node):
        var = self._next()
        self.result.append(f'{node.name} {var};')
        for (field_name, field) in node.fields.items():
            field_var = self.visit(field)
            if self._is_array(field):
                self.result.append(
                    f'memcpy({var}.{field_name}, {field_var}, sizeof({field_var}));')
            else:
                self.result.append(f'{var}.{field_name} = {field_var};')
        return var

    def visit_Alias(self, node):
        return self.visit(node.type)

class ResultReader(NodeVisitor):
    """
    Class to read the results of a KLEE run and convert them to Python values.
    """

    def __init__(self, assignment: Dict[str, int]):
        self.number = 0
        self.assignment = assignment
        self.mx = 0
        for key in assignment:
            self.mx = max(int(key[-1]), self.mx)

    def _lookup(self):
        n = self._next()
        while n not in self.assignment:
            n = self._next()
            if int(n[-1]) > self.mx:
                break
        if n in self.assignment:
            return self.assignment[n]
        raise Exception("Invalid assignment")

    def _next(self):
        n = self.number
        self.number = self.number + 1
        return f'x{n}'

    def visit_Void(self, node):
        raise Exception('Cannot create an instance of the Void type')

    def visit_Bool(self, node):
        return bool(self._lookup())

    def visit_Char(self, node):
        return chr(self._lookup())

    def visit_Int(self, node):
        return int(self._lookup())

    def visit_String(self, node):
        self._next()  # char[] variable
        str = ""
        done = False
        for _ in range(0, node.maxsize):
            c = self.visit(node.char_type)
            if c == '\0':
                done = True
            if not done:
                str = str + c
        return str

    def visit_Enum(self, node):
        return node.values[self._lookup()]

    def visit_Array(self, node):
        self._next()  # array variable
        result = []
        for _ in range(0, node.maxsize):
            result.append(self.visit(node.element_type))
        return tuple(result)

    def visit_Struct(self, node):
        self._next()  # struct variable
        result = {}
        for (field_name, field) in node.fields.items():
            result[field_name] = self.visit(field)
        return result

    def visit_Alias(self, node):
        return self.visit(node.type)


class RegexModule(Function):
    """_summary_
    A module that checks for regex matches.
    """
    def __init__(self, name: str, regex_str: str, input: Parameter):
        self.name = name
        self.inputs = [input]
        self.regex_str = regex_str
        self.precondition = None
        self.description = f'Module that checks if the input matches the regex: {regex_str}'
        self.regex = self.get_regex()
        self.result = Parameter(name="result", type=Bool(), description="True if the input matches the regex, False otherwise")

    @staticmethod
    def regex_parser(regex: str) -> re.Regex:
        if regex == "":
            return re.Empty()

        stack = []
        i = 0
        # print("Parsing regex:", regex)
        while i < len(regex):
            char = regex[i]

            if char == '*':
                r = stack.pop()
                stack.append(re.star(r))

            elif char == '(':
                j = i + 1
                paren_count = 1
                while j < len(regex) and paren_count > 0:
                    if regex[j] == '(':
                        paren_count += 1
                    elif regex[j] == ')':
                        paren_count -= 1
                    j += 1
                sub_regex = regex[i + 1:j - 1]
                stack.append(RegexModule.regex_parser(sub_regex))
                i = j - 1

            elif char == '[':
                j = i + 1
                options = []
                while j < len(regex) and regex[j] != ']':
                    if j + 1 < len(regex) and regex[j + 1] == '-':
                        low = regex[j]
                        if regex[j+2] == '\\':
                            high = regex[j + 3]
                            j += 3
                        else:
                            high = regex[j + 2]
                            j += 2
                        options.append(re.chars(low, high))

                    elif regex[j] == '\\':
                        low = regex[j + 1]
                        high = regex[j + 1]
                        j += 1
                        options.append(re.chars(low, high))

                    else:
                        low = regex[j]
                        high = regex[j]
                        options.append(re.chars(low, high))
                    j += 1

                if len(options) == 1:
                    stack.append(options[0])
                elif len(options) > 1:
                    stack.append(re.choice(*options))
                i = j

            elif char == '|':
                r1 = stack.pop()
                sub_regex = regex[i+1:]
                r2 = RegexModule.regex_parser(sub_regex)
                stack.append(re.choice(r1, r2))
                break

            else:
                if char == '\\':
                    i += 1
                char = regex[i]
                stack.append(re.chars(char, char))


            i += 1   

        return re.seq(*stack) if len(stack) > 1 else stack[0]

    def get_regex(self) -> re.Regex:
        regex = self.regex_str
        return self.regex_parser(regex)

#!/usr/bin/env python3
"""Public fixtures only. Runs the CLI through bounded, ordinary OS pipes."""
import argparse
import ctypes
import errno
import json
import math
import os
from pathlib import Path
import resource
import selectors
import signal
import stat
import subprocess
import sys
import time

CAP_OUT = 512 * 1024 * 1024
CAP_ERR = 1024 * 1024
LIBC = ctypes.CDLL(None, use_errno=True)
ACTIVE = set()


def prctl(option, argument):
    if LIBC.prctl(ctypes.c_int(option), ctypes.c_ulong(argument),
                  ctypes.c_ulong(0), ctypes.c_ulong(0), ctypes.c_ulong(0)) != 0:
        number = ctypes.get_errno()
        raise OSError(number, os.strerror(number))


def supervise():
    if os.uname().machine != 'x86_64':
        raise RuntimeError('The public development profile requires Linux x86-64.')
    try:
        os.kill(os.getpid(), 0)  # Check the supervisor-only signal permission.
        prctl(36, 1)  # PR_SET_CHILD_SUBREAPER: adopt orphaned descendants.
    except OSError as exc:
        raise RuntimeError('Public supervisor needs the development overlay in WORKER-PROFILE.md.') from exc


def candidate_filter():
    # Only the supervisor gets the development overlay permissions. Children
    # cannot leave their process group, even through a raw syscall or exec.
    class Filter(ctypes.Structure):
        _fields_ = [('code', ctypes.c_ushort), ('jt', ctypes.c_ubyte),
                    ('jf', ctypes.c_ubyte), ('k', ctypes.c_uint)]
    class Program(ctypes.Structure):
        _fields_ = [('length', ctypes.c_ushort), ('filters', ctypes.POINTER(Filter))]
    instructions = [(0x20, 0, 0, 4), (0x15, 1, 0, 0xc000003e),
                    (0x06, 0, 0, 0x80000000), (0x20, 0, 0, 0),
                    (0x35, 0, 1, 0x40000000), (0x06, 0, 0, 0x80000000)]
    for syscall in (62, 200, 234, 109, 112):  # kill/tkill/tgkill/setpgid/setsid
        instructions += [(0x15, 0, 1, syscall), (0x06, 0, 0, 0x00050000 | errno.EPERM)]
    instructions += [(0x06, 0, 0, 0x7fff0000)]
    filters = (Filter * len(instructions))(*(Filter(*item) for item in instructions))
    program = Program(len(filters), filters)
    prctl(38, 1)  # PR_SET_NO_NEW_PRIVS
    if LIBC.prctl(22, 2, ctypes.byref(program), 0, 0) != 0:
        number = ctypes.get_errno()
        raise OSError(number, os.strerror(number))


def pairs(items):
    value = {}
    for key, item in items:
        if key in value:
            raise ValueError("duplicate key")
        value[key] = item
    return value


def strict_json(raw):
    def bad_constant(value):
        raise ValueError("non-finite number")
    def finite_float(value):
        number = float(value)
        if not math.isfinite(number):
            raise ValueError("non-finite number")
        return number
    return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                      parse_constant=bad_constant, parse_float=finite_float)


def child_limits(mask):
    os.setpgid(0, 0)
    for kind, limits in [(resource.RLIMIT_AS, (2 << 30, 2 << 30)),
                         (resource.RLIMIT_CPU, (180, 181)),
                         (resource.RLIMIT_NPROC, (64, 64)),
                         (resource.RLIMIT_NOFILE, (256, 256)),
                         (resource.RLIMIT_FSIZE, (64 << 20, 64 << 20)),
                         (resource.RLIMIT_STACK, (8 << 20, resource.RLIM_INFINITY)),
                         (resource.RLIMIT_CORE, (0, 0))]:
        resource.setrlimit(kind, limits)
    candidate_filter()
    signal.pthread_sigmask(signal.SIG_SETMASK, mask)


def stop(child):
    # The group leader is deliberately not reaped before signalling: its PID
    # reserves the group identity. No UID-wide or unrelated-process signals.
    mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGINT, signal.SIGTERM})
    try:
        if getattr(child, '_public_cleaned', False):
            return
        if not hasattr(child, '_public_cleanup_deadline'):
            child._public_cleanup_deadline = time.monotonic() + 5
        deadline = child._public_cleanup_deadline
        if not getattr(child, '_public_signalled', False):
            try:
                os.killpg(child.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            child._public_signalled = True
        child.wait(timeout=max(.001, deadline - time.monotonic()))
        while True:
            try:
                pid, _ = os.waitpid(-child.pid, os.WNOHANG)
            except ChildProcessError:
                child._public_cleaned = True
                return
            if time.monotonic() >= deadline:
                raise RuntimeError('Public descendant cleanup did not complete; no result accepted.')
            if pid == 0:
                time.sleep(.01)
    finally:
        signal.pthread_sigmask(signal.SIG_SETMASK, mask)


def wait_exit(child, deadline):
    # WNOWAIT preserves the leader PID until stop() owns cleanup of the group.
    while True:
        result = os.waitid(os.P_PID, child.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
        if result is not None:
            return result.si_status if result.si_code == os.CLD_EXITED else -result.si_status
        if time.monotonic() >= deadline:
            raise ValueError('wall timeout')
        time.sleep(min(.01, max(0, deadline - time.monotonic())))


def run_child(candidate, data):
    if os.geteuid() == 0:
        raise RuntimeError("Refusing root candidate execution; run in the task container or a nonprivileged sandbox.")
    supervise()
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C", "LC_ALL": "C",
           "HOME": "/workspace", "TMPDIR": "/workspace/tmp",
           "PYTHONDONTWRITEBYTECODE": "1", "PYTHONUNBUFFERED": "1",
           "PYTHONHASHSEED": "0", "OMP_NUM_THREADS": "1",
           "OPENBLAS_NUM_THREADS": "1", "MKL_NUM_THREADS": "1"}
    selector = selectors.DefaultSelector()
    child = None
    streams = []
    captured = [bytearray(), bytearray()]
    offset = 0
    started = time.monotonic()
    try:
        mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGINT, signal.SIGTERM})
        try:
            child = subprocess.Popen([sys.executable, "-I", "-B", str(candidate)],
                                     stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                     stderr=subprocess.PIPE, close_fds=True,
                                     preexec_fn=lambda: child_limits(mask), env=env)
            ACTIVE.add(child)
            streams = [child.stdin, child.stdout, child.stderr]
        except subprocess.SubprocessError as exc:
            raise RuntimeError('Candidate setup failed; use the development overlay in WORKER-PROFILE.md.') from exc
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, mask)
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        selector.register(child.stdin, selectors.EVENT_WRITE, -1)
        selector.register(child.stdout, selectors.EVENT_READ, 0)
        selector.register(child.stderr, selectors.EVENT_READ, 1)
        while selector.get_map():
            left = 120 - (time.monotonic() - started)
            if left <= 0:
                raise ValueError("wall timeout")
            for key, _ in selector.select(min(left, 0.1)):
                stream, index = key.fileobj, key.data
                if index == -1:
                    try:
                        count = os.write(stream.fileno(), data[offset:offset + 65536])
                        offset += count
                    except BrokenPipeError:
                        offset = len(data)
                    except BlockingIOError:
                        continue
                    if offset == len(data):
                        selector.unregister(stream)
                        stream.close()
                else:
                    limit = (CAP_OUT, CAP_ERR)[index]
                    try:
                        chunk = os.read(stream.fileno(), min(65536, limit - len(captured[index]) + 1))
                    except BlockingIOError:
                        continue
                    if not chunk:
                        selector.unregister(stream)
                        stream.close()
                    elif len(chunk) + len(captured[index]) > limit:
                        raise ValueError(("stdout", "stderr")[index] + " limit")
                    else:
                        captured[index].extend(chunk)
        code = child.returncode if child.returncode is not None else wait_exit(child, started + 120)
        if code != 0:
            raise ValueError("candidate exited " + str(code))
        value = strict_json(bytes(captured[0]))
        if not isinstance(value, dict):
            raise ValueError("output is not an object")
        return value
    finally:
        try:
            if child is not None:
                stop(child)
                ACTIVE.discard(child)
        finally:
            selector.close()
            for stream in streams:
                stream.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("candidate", type=Path, help="project directory containing campaign_cli.py and src/")
    args = parser.parse_args()
    project = args.candidate.absolute()
    if project.is_symlink() or not project.is_dir():
        raise ValueError("candidate must be a regular project directory")
    total = 0
    entries = 0
    for path in project.rglob("*"):
        info = path.lstat(); entries += 1
        if path.is_symlink() or not (stat.S_ISREG(info.st_mode) or stat.S_ISDIR(info.st_mode)):
            raise ValueError("project contains a non-regular entry")
        if stat.S_ISREG(info.st_mode):
            if info.st_nlink != 1: raise ValueError("project contains a hard link")
            total += info.st_size
    if total > 8 * 1024 * 1024 or entries > 256:
        raise ValueError("project exceeds submission bounds")
    candidate = project / "campaign_cli.py"
    candidate.read_bytes().decode("utf-8")
    files = sorted((Path(__file__).parent / "examples").glob("*.input.json"))
    if not files:
        raise RuntimeError("public fixtures missing")
    passed = 0
    for path in files:
        try:
            actual = run_child(candidate, path.read_bytes())
            expected = strict_json(path.with_name(path.name.replace(".input.", ".expected.")).read_bytes())
            # JSON serialization distinguishes bool/int and rejects numeric aliases.
            if json.dumps(actual, sort_keys=True) != json.dumps(expected, sort_keys=True):
                raise ValueError("response differs from public expectation")
            passed += 1
            print("PASS " + path.name)
        except (ValueError, OSError, subprocess.TimeoutExpired) as exc:
            print("FAIL " + path.name + ": " + str(exc))
    print(str(passed) + "/" + str(len(files)) + " public fixtures passed")
    return 0 if passed == len(files) else 1


if __name__ == "__main__":
    def interrupted(signum, frame):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, signal.SIG_IGN)
        raise KeyboardInterrupt()
    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, interrupted)
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        print('INTERRUPTED: no public result accepted', file=sys.stderr)
        sys.exit(130)
    except (ValueError, OSError, RuntimeError) as exc:
        print("CHECK_ERROR: " + str(exc), file=sys.stderr)
        sys.exit(2)
    finally:
        # Also covers an interrupt arriving while run_child's finally begins.
        for child in list(ACTIVE):
            stop(child)

