"""Regular-language pattern objects: strict grammar parsing and matching.

Patterns are printable-ASCII expressions over Latin-1 code points with the
documented union/sequence/repetition grammar and literal, group, and character
class atoms.  Precedence is repetition, sequence, then union.  Matching is
whole-string (full) membership.
"""


class Node(object):
    """Base class for pattern syntax nodes."""


class Empty(Node):
    """Matches the empty string."""

    __slots__ = ()


class Lit(Node):
    """Matches one literal code point."""

    __slots__ = ('cp',)

    def __init__(self, cp):
        self.cp = cp


class Class(Node):
    """Matches one code point inside a union of inclusive ranges."""

    __slots__ = ('ranges',)

    def __init__(self, ranges):
        self.ranges = ranges


class Seq(Node):
    """Matches a sequence of nodes in order."""

    __slots__ = ('parts',)

    def __init__(self, parts):
        self.parts = parts


class Alt(Node):
    """Matches any one of the alternatives."""

    __slots__ = ('alts',)

    def __init__(self, alts):
        self.alts = alts


class Star(Node):
    """Matches zero or more repetitions of the inner node."""

    __slots__ = ('inner',)

    def __init__(self, inner):
        self.inner = inner


class _NFA(object):
    """Thompson NFA under construction."""

    __slots__ = ('eps', 'trans')

    def __init__(self):
        self.eps = []
        self.trans = []

    def new(self):
        self.eps.append([])
        self.trans.append([])
        return len(self.eps) - 1

    def add_eps(self, a, b):
        self.eps[a].append(b)

    def add_tr(self, a, lo, hi, b):
        self.trans[a].append((lo, hi, b))

    def frag(self, node):
        if isinstance(node, Empty):
            s = self.new()
            a = self.new()
            self.add_eps(s, a)
            return s, a
        if isinstance(node, Lit):
            s = self.new()
            a = self.new()
            self.add_tr(s, node.cp, node.cp, a)
            return s, a
        if isinstance(node, Class):
            s = self.new()
            a = self.new()
            for (lo, hi) in node.ranges:
                self.add_tr(s, lo, hi, a)
            return s, a
        if isinstance(node, Seq):
            s = a = None
            for part in node.parts:
                ps, pa = self.frag(part)
                if s is None:
                    s, a = ps, pa
                else:
                    self.add_eps(a, ps)
                    a = pa
            return s, a
        if isinstance(node, Alt):
            s = self.new()
            a = self.new()
            for alt in node.alts:
                bs, ba = self.frag(alt)
                self.add_eps(s, bs)
                self.add_eps(ba, a)
            return s, a
        if isinstance(node, Star):
            s = self.new()
            a = self.new()
            bs, ba = self.frag(node.inner)
            self.add_eps(s, bs)
            self.add_eps(s, a)
            self.add_eps(ba, bs)
            self.add_eps(ba, a)
            return s, a
        raise ValueError('unknown pattern node')


class Pattern(object):
    """A parsed regular-language pattern with a cached matcher."""

    __slots__ = ('node', '_nfa', '_start', '_accept')

    def __init__(self, node):
        self.node = node
        self._nfa = None
        self._start = None
        self._accept = None

    @staticmethod
    def parse(text):
        return Pattern(parse_pattern(text))

    def _build(self):
        if self._nfa is None:
            nfa = _NFA()
            start, accept = nfa.frag(self.node)
            self._nfa = nfa
            self._start = start
            self._accept = accept

    def match(self, s):
        self._build()
        nfa = self._nfa
        eps = nfa.eps
        trans = nfa.trans

        def closure(states):
            seen = set(states)
            stack = list(states)
            while stack:
                st = stack.pop()
                for t in eps[st]:
                    if t not in seen:
                        seen.add(t)
                        stack.append(t)
            return seen

        cur = closure([self._start])
        accept = self._accept
        for ch in s:
            cp = ord(ch)
            nxt = []
            for st in cur:
                for (lo, hi, t) in trans[st]:
                    if lo <= cp <= hi:
                        nxt.append(t)
            if not nxt:
                return False
            cur = closure(nxt)
        return accept in cur


def parse_pattern(text):
    """Parse pattern text into a pattern node tree."""
    s = text
    n = len(s)
    i = 0

    def parse_alt():
        nonlocal i
        alts = [parse_seq()]
        while i < n and s[i] == '|':
            i += 1
            alts.append(parse_seq())
        if len(alts) == 1:
            return alts[0]
        return Alt(alts)

    def parse_seq():
        nonlocal i
        parts = []
        while i < n and s[i] not in '|)':
            parts.append(parse_atom())
        if not parts:
            return Empty()
        if len(parts) == 1:
            return parts[0]
        return Seq(parts)

    def parse_atom():
        nonlocal i
        c = s[i]
        i += 1
        if c == '(':
            node = parse_alt()
            i += 1  # documented grammar guarantees ')'
        elif c == '[':
            node = parse_class()
        elif c == '\\':
            node = Lit(ord(s[i]))
            i += 1
        else:
            node = Lit(ord(c))
        while i < n and s[i] == '*':
            i += 1
            node = Star(node)
        return node

    def parse_class():
        nonlocal i
        items = []
        while True:
            c = s[i]
            i += 1
            if c == ']':
                break
            if c == '\\':
                low = s[i]
                i += 1
            else:
                low = c
            if i + 1 < n and s[i] == '-' and s[i + 1] != ']':
                i += 1
                c2 = s[i]
                i += 1
                if c2 == '\\':
                    high = s[i]
                    i += 1
                else:
                    high = c2
                items.append((ord(low), ord(high)))
            else:
                items.append((ord(low), ord(low)))
        return Class(items)

    return parse_alt()


_CACHE = {}


def compile_pattern(text):
    """Parse (with memoization) a pattern string."""
    pat = _CACHE.get(text)
    if pat is None:
        pat = Pattern.parse(text)
        _CACHE[text] = pat
    return pat


def ismatch(pattern_text, s):
    """Full membership of the string in the pattern's regular language."""
    return compile_pattern(pattern_text).match(s)
