"""Corpus identity for recovered symbolic inputs.

A corpus identity is (entry, recovered input values).  Model results, raw
bytes after a string NUL, transport arguments, object order, and preparation
metadata are excluded.  JSON type identity is retained: arrays, objects,
booleans, and integers never collide across kinds and empty arrays differ
from empty objects.  Different entries never merge.
"""


def value_key(types, tname, value):
    """Type-aware fingerprint of one recovered value."""
    d = types.defs[tname]
    kind = d.kind
    if kind == 'alias':
        return value_key(types, d.target, value)
    if kind == 'array':
        return ('a', tuple(value_key(types, d.element, v) for v in value))
    if kind == 'struct':
        return ('o', tuple((fname, value_key(types, ft, value[fname]))
                           for (fname, ft) in d.fields))
    if kind == 'bool':
        return ('b', value)
    if kind == 'int':
        return ('i', value)
    return ('s', value)


def identity(types, entry, params, inputs):
    """Corpus identity key for one usable record."""
    return (entry, tuple((name, value_key(types, tname, inputs[name]))
                         for (name, tname) in params))
